<template>
  <div>
    <div class="btn-group mb-2">
<button type="button" class="btn btn-success me-2" @click="handleStatus(3)" :disabled="spinner">Approve</button>
<button type="button" class="btn btn-danger me-2" @click="handleStatus(4)" :disabled="spinner">Reject</button>
<button type="button" class="btn btn-info me-2" @click="handleStatus(14)" :disabled="spinner">Remark</button>
<button type="button" class="btn btn-warning" @click="handleStatus(17)" :disabled="spinner">On Hold</button>
    </div>

    <div v-if="status && block" class="mb-2 text-center">
      <span class="badge rounded-pill"
        :class="{
          'bg-danger': status == 4,
          'bg-success': status == 3,
          'bg-info': status == 14,
          'bg-warning': status == 17
        }"
        style="font-size: 1rem;"
      >
        {{ status == 3 ? 'Approve Request' : status == 4 ? 'Reject Request' : status == 17 ? 'Hold Request' : 'Fill Remark' }}
      </span>
    </div>

    <div class="input-group" v-if="status">
      <input type="text" class="form-control"
        :placeholder="status == 3 ? 'Enter Approval Remark' : status == 4 ? 'Enter Rejection Remark' : 'Enter Remark'"
        v-model="remark"
        v-if="block"
        >
      <button v-if="block" type="submit" class="btn btn-primary me-2" :disabled="spinner">
        <span v-if="spinner" v-html="loadingSpinner()"></span>
        <span v-else>Save</span>
      </button>
    </div>
  </div>
</template>

<script setup>
import { ref, watch } from 'vue'

const props = defineProps({
  spinner: Boolean,
  loadingSpinner: Function,
  modelValue: Number,
  blockValue: Boolean,  
  remarkValue: String
})

const emit = defineEmits(['update:blockValue','update:modelValue', 'update:remarkValue'])

const block = ref(props.blockValue || false)
const status = ref(props.modelValue || null)
const remark = ref(props.remarkValue || '')


watch(() => props.modelValue, val => status.value = val)
watch(() => props.remarkValue, val => remark.value = val)
watch(() => props.blockValue, val => block.value = val)  

watch(block, val => emit('update:blockValue', val))
watch(status, val => emit('update:modelValue', val))
watch(remark, val => emit('update:remarkValue', val))

const handleStatus = (newStatus) => {
  if (status.value === newStatus && block.value) {
    block.value = false
  } else {
    status.value = newStatus
    block.value = true
  }
}
</script>
